#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Generate the tile font table (F-WASM-13) from the DejaVu fonts the shell already bundles.

Output (both written by this one script, so the two renderers cannot differ):
  crates/iyakki-tile-host/src/tilefont.bin   read by render.rs (include_bytes)
  the block between the TILEFONT markers in crates/iyakki-agent/src/webservice/ui/tilerender.js (base64)

Format of the table: "IYTF", u8 faces, u8 sizes, the sizes (u8 each), then for each face, for each size, 191 glyphs
(U+0020..U+007E, U+00A0..U+00FF). A glyph is a cell of advance(size) x size pixels (advance = max(1, size*6/7), the ABI's),
row by row, one bit per pixel, most significant bit first, padded to a whole byte. A set bit is full colour, a clear bit nothing.
Table face i is the ABI's face i: 0 DejaVu Sans, 1 DejaVu Sans Mono, 2 DejaVu Sans Bold (any other face number draws as 0). DejaVu licence: Bitstream Vera licence with
public-domain changes (crates/iyakki-shell/assets/DEJAVU-LICENSE.txt); the table is a derived work and carries that notice.

  python3 dist/tilefont/gen.py            write both files
  python3 dist/tilefont/gen.py --check    fail if either file differs from what the fonts give
Needs Pillow with FreeType on the build machine only (not shipped, not a build dependency of the OS).
"""
import base64, os, re, sys
from PIL import Image, ImageDraw, ImageFont

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
FONTS = [os.path.join(ROOT, "crates/iyakki-shell/assets/" + n) for n in ("DejaVuSans.ttf", "DejaVuSansMono.ttf", "DejaVuSans-Bold.ttf")]
SIZES = [8, 10, 12, 16, 22, 32]
CODES = list(range(0x20, 0x7F)) + list(range(0xA0, 0x100))
OVER = 8          # oversampling before the area-average down to the cell
STRETCH = 1.2     # the ABI cell (6/7 of the size) is wider than the font's own advance: widen the shape a little
BIN = os.path.join(ROOT, "crates/iyakki-tile-host/src/tilefont.bin")
JS = os.path.join(ROOT, "crates/iyakki-agent/src/webservice/ui/tilerender.js")

def adv(size): return max(1, size * 6 // 7)

def glyph(font_path, size, cp):
    aw = adv(size)
    em = round(OVER * size / 1.164)             # ascent + descent of the font is about 1.164 em: the line fits the cell height
    f = ImageFont.truetype(font_path, em)
    asc, desc = f.getmetrics()
    ox = em                                       # origin of the pen inside the scratch picture
    g = Image.new("L", (em * 3, asc + desc), 0)
    ImageDraw.Draw(g).text((ox, 0), chr(cp), font=f, fill=255)
    centre = ox + f.getlength(chr(cp)) / 2        # centre of the glyph's own advance
    box = g.getbbox()
    sx = STRETCH
    if box:
        half = max(centre - box[0], box[2] - centre, 1)
        sx = min(STRETCH, 0.98 * aw * OVER / (2 * half))
    g = g.resize((max(1, round(g.width * sx)), g.height), Image.BILINEAR)
    cell = Image.new("L", (aw * OVER, size * OVER), 0)
    cell.paste(g, (round(aw * OVER / 2 - centre * sx), 0))
    small = cell.resize((aw, size), Image.BOX)   # area average = coverage
    px = [[small.getpixel((x, y)) for x in range(aw)] for y in range(size)]
    on = [[v >= 100 for v in row] for row in px]
    peak = max(max(r) for r in px)
    if peak >= 20 and not any(any(r) for r in on):
        # a hairline mark (an apostrophe at the smallest size) must not vanish: keep its strongest pixels
        on = [[v >= peak * 0.6 for v in row] for row in px]
    bits = bytearray()
    acc = n = 0
    for y in range(size):
        for x in range(aw):
            acc = (acc << 1) | (1 if on[y][x] else 0)
            n += 1
            if n == 8:
                bits.append(acc); acc = n = 0
    if n:
        bits.append(acc << (8 - n))
    return bytes(bits)

def build():
    out = bytearray(b"IYTF")
    out += bytes([len(FONTS), len(SIZES)]) + bytes(SIZES)
    for fp in FONTS:
        for s in SIZES:
            for cp in CODES:
                out += glyph(fp, s, cp)
    return bytes(out)

def js_block(b):
    t = base64.b64encode(b).decode()
    lines = [t[i:i + 120] for i in range(0, len(t), 120)]
    return "  // TILEFONT-BEGIN (generated by dist/tilefont/gen.py from DejaVu Sans, Sans Mono and Sans Bold: Bitstream Vera licence with public-domain changes, see\n" \
           "  // crates/iyakki-shell/assets/DEJAVU-LICENSE.txt; do not edit)\n  const FONT_B64 =\n" + \
           "\n".join('    "%s"%s' % (l, " +" if i < len(lines) - 1 else ";") for i, l in enumerate(lines)) + "\n  // TILEFONT-END"

def main():
    b = build()
    js = open(JS).read()
    new_js = re.sub(r"  // TILEFONT-BEGIN.*?// TILEFONT-END", lambda m: js_block(b), js, flags=re.S)
    if "--check" in sys.argv:
        ok = os.path.exists(BIN) and open(BIN, "rb").read() == b and new_js == js
        print("tile font table is up to date" if ok else "tile font table DIFFERS from the fonts")
        sys.exit(0 if ok else 1)
    open(BIN, "wb").write(b)
    open(JS, "w").write(new_js)
    print("wrote %d bytes" % len(b))

if __name__ == "__main__":
    main()
